#include <cstdlib>
#include <iostream>
#include "strut/lexer.h"
#include "strut/parser.h"
#include "strut/sema.h"
#include "strut/source.h"
namespace{void req(bool c,const char*m){if(!c){std::cerr<<"FAIL: "<<m<<'\n';std::exit(1);}} strut::SemanticResult sema(std::string t){strut::SourceFile s("x.p",std::move(t));strut::Lexer l(s);auto lx=l.lex();req(lx.ok(),"lex");strut::Parser p(lx.tokens);auto pr=p.parse();req(pr.ok(),"parse");strut::SemanticAnalyzer a;return a.analyze(pr.program);}}
int main(){req(sema("x := 1; { x := 2; }").ok(),"nested shadowing allowed");req(!sema("x := 1; x := 2;").ok(),"same-scope duplicate rejected");req(!sema("function f(int x) -> void { x := 2; }").ok(),"parameter duplicate rejected");req(sema("x := 1; function x() -> void;").ok(),"value/function namespaces separate");req(sema("type user_id := uint_64; user_id id := 7;").ok(),"user alias");req(!sema("type A := B; type B := A;").ok(),"alias cycle rejected");req(sema("x := 1; int_64 y := x; double z := x;").ok(),"inference and widening");req(!sema("const x := 1; x = 2;").ok(),"const enforced");req(!sema("x := 1; x = \"bad\";").ok(),"assignment type checked");req(sema("function main() -> void : ExecError { p := process(\"echo\", [\"hi\"]); p.in.close(); line := p.out.read_line(); code := p.wait(); print(line); print(code); }").ok(),"process api types");req(sema("function risky() -> void : Error { throw Error(\"x\"); } function main() -> void { try { risky(); } catch (Error err) { print(err); } }").ok(),"caught checked error");req(sema("struct User { string name; } function main() -> void { p := ptr(User { name: \"Ada\" }); unsafe { ptr<User> r := raw(p); print(r->name); } }").ok(),"raw pointer arrow access in unsafe");req(sema("extern \"C\" function c_add(int a, int b) -> int; function main() -> void { unsafe { print(c_add(2,3)); } }").ok(),"extern C call in unsafe");req(!sema("extern \"C\" function c_add(int a, int b) -> int; function main() -> void { print(c_add(2,3)); }").ok(),"extern C call outside unsafe rejected");return 0;}
